# WARNING: Under review - generated by LLM.

from types import SimpleNamespace

from .tiny_llm_base import (
    AgentLimits,
    ToolAction,
    initial_messages,
    run_agent,
)


class FakeWorkspace:
    """Minimal Day 1 tool boundary; later days implement the real workspace."""

    def __init__(self, root):
        self.policy = SimpleNamespace(
            root=root, allow_writes=False, allowed_commands=()
        )
        self.available_tools = frozenset({"read_file"})
        self.cancellation = None
        self.session_log = None
        self.modified_files = set()
        self.uncertain_modified_files = set()
        self.retained_recovery_files = set()
        self.command_side_effects_untracked = False
        self.command_cleanup_incomplete = False
        self.executed = []

    def execute(self, action, *, tool_call_id=None):
        self.executed.append(action)
        return "README contents"


def responses(*items):
    """Return scripted model responses for loop behavior tests."""

    queue = iter(items)
    return lambda messages: next(queue)


def test_task_1_initial_messages_preserve_the_task():
    messages = initial_messages("inspect the project", "system instructions")

    assert messages == [
        {"role": "system", "content": "system instructions"},
        {"role": "user", "content": "inspect the project"},
    ]


def test_task_1_rejects_an_empty_task():
    try:
        initial_messages("   ", "system instructions")
    except ValueError as error:
        assert "must not be empty" in str(error)
    else:
        assert False, "expected an empty task to be rejected"


def test_task_2_executes_a_tool_appends_its_result_and_finishes():
    workspace = FakeWorkspace("/tmp")
    responses_queue = iter(
        [
            '{"tool":"read_file","path":"README.md"}',
            '{"final":"inspected README"}',
        ]
    )

    result = run_agent(
        "inspect the project", lambda messages: next(responses_queue), workspace
    )

    assert result.completed
    assert result.reason == "completed"
    assert result.final == "inspected README"
    assert workspace.executed == [ToolAction("read_file", {"path": "README.md"})]


def test_task_3_returns_invalid_and_unknown_actions_to_the_model():
    workspace = FakeWorkspace("/tmp")
    responses_queue = iter(
        [
            "not json",
            '{"tool":"run_shell","argv":["rm","-rf","."]}',
            '{"final":"recovered"}',
        ]
    )

    result = run_agent(
        "inspect the project", lambda messages: next(responses_queue), workspace
    )

    assert result.completed
    assert workspace.executed == []
    assert [event.action for event in result.events[:2]] == [None, None]
    assert all(event.result.startswith("error:") for event in result.events[:2])


def test_task_4_stops_at_the_step_budget():
    workspace = FakeWorkspace("/tmp")

    result = run_agent(
        "inspect the project",
        lambda _messages: '{"tool":"read_file","path":"README.md"}',
        workspace,
        AgentLimits(max_steps=2, max_identical_actions=3),
    )

    assert not result.completed
    assert result.reason == "step_limit"
    assert len(result.events) == 2
    assert len(workspace.executed) == 2


def test_task_5_agent_observes_then_finishes():
    workspace = FakeWorkspace("/tmp")
    generate = responses(
        '{"tool":"read_file","path":"README.md"}',
        '{"final":"inspected README"}',
    )

    result = run_agent("inspect the project", generate, workspace)

    assert result.completed
    assert result.final == "inspected README"
    assert result.reason == "completed"
    assert len(result.events) == 2


def test_task_6_agent_recovers_from_invalid_json():
    workspace = FakeWorkspace("/tmp")
    generate = responses("not json", '{"final":"recovered"}')

    result = run_agent("inspect the project", generate, workspace)

    assert result.completed
    assert result.events[0].result.startswith("error:")


def test_task_7_agent_stops_repeated_actions():
    workspace = FakeWorkspace("/tmp")
    generate = responses(*['{"tool":"read_file","path":"README.md"}'] * 3)

    result = run_agent(
        "inspect the project",
        generate,
        workspace,
        AgentLimits(max_steps=5, max_identical_actions=2),
    )

    assert not result.completed
    assert result.reason == "repeated_action_limit"
